/// <summary>
/// The <c>METDeleteRejectedFreeTextInvoiceMainController</c> class for the batch job to delete rejected free text invoices.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
class METDeleteRejectedFreeTextInvoiceMainController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Main method of the batch job.
/// </summary>
/// <param name="_args">The arguments passed to the batch job.</param>
public static void main(Args _args)
{
    METDeleteRejectedFreeTextInvoiceMainController controller = METDeleteRejectedFreeTextInvoiceMainController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// Constructs an instance of the <c>METDeleteRejectedFreeTextInvoiceMainController</c> class.
/// </summary>
/// <param name="_executionMode">The execution mode for the operation, either synchronous or scheduled batch.</param>
/// <returns>An instance of the <c>METDeleteRejectedFreeTextInvoiceMainController</c> class.</returns>
public static METDeleteRejectedFreeTextInvoiceMainController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METDeleteRejectedFreeTextInvoiceMainController controller = new METDeleteRejectedFreeTextInvoiceMainController();
    controller.parmExecutionMode(_executionMode);

    return controller;
}

/// <summary>
/// Initializes a new instance of the <c>METDeleteRejectedFreeTextInvoiceMainController</c> class.
/// </summary>
protected void new()
{
    super(classStr(METDeleteRejectedFreeTextInvoiceMainService),
            methodStr(METDeleteRejectedFreeTextInvoiceMainService, processOperation),
            SysOperationExecutionMode::ScheduledBatch);
}

/// <summary>
/// Sets the caption of the batch job.
/// </summary>
/// <returns>The description of the class.</returns>
public ClassDescription defaultCaption()
{
    return "@MET:METDeleteRejectedFTI";
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions.
/// </summary>
/// <returns>
/// <c>true</c> if the batch task is retryable; otherwise, <c>false</c>.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}
